 absent:async(id,n,ms)=>ops.docker(['container','ls','-a','--no-trunc','--filter','id='+id,'--format','{{.ID}}'],undefined,ms).trim()===''&&ops.docker(['network','ls','--no-trunc','--filter','id='+n,'--format','{{.ID}}'],undefined,ms).trim()==='',
 artifactCleanup:async(child,ownerRaw)=>{await checkChain(fixed.artifact,{leaf:true,mode:0o700});await ordinary(fixed.artifact+'/owner.json',p.uid,0o600);if(await readFile(fixed.artifact+'/owner.json','utf8')!==ownerRaw)throw new UnknownOutcome('ARTIFACT');const walk=async path=>{for(const name of await readdir(path)){const item=path+'/'+name,st=await lstat(item);if(st.uid!==p.uid||st.isSymbolicLink()||!st.isFile()&&!st.isDirectory()||st.isFile()&&st.nlink!==1)throw new UnknownOutcome('ARTIFACT');if(st.isDirectory())await walk(item);}};await walk(fixed.artifact);verify();await rm(fixed.artifact,{recursive:true});for(const path of [...anchors.keys()])if(path===fixed.artifact||path.startsWith(fixed.artifact+'/'))anchors.delete(path);const parent=fixed.artifact.slice(0,fixed.artifact.lastIndexOf('/'));await checkChain(parent,{leaf:true,mode:0o700});if((await readdir(parent)).length)throw new UnknownOutcome('ARTIFACT');await rmdir(parent);anchors.delete(parent);},
