export async function main(args=[],env={},factory=actualPorts){if(args.length===0||args.length===1&&args[0]==='--plan')return{schemaVersion:1,purpose:'IX01_ACTUAL_JOURNEY_PREPARER_SOURCE',actualExecuted:false,sqlHead:fixed.sqlHead,selected:105,source:fixed.source,actualApprovalRequired:true};if(args.length!==1||args[0]!=='--run'||env.ANVIL_IX01_JOURNEY_OPT_IN!=='EXACT_PLAN_APPROVED')reject('NOT_OPTED_IN');const raw=env.ANVIL_IX01_JOURNEY_PLAN,digest=env.ANVIL_IX01_JOURNEY_PLAN_SHA256;if(typeof raw!=='string'||Buffer.byteLength(raw)>65536||!hex(digest,64)||hash(raw)!==digest)reject('PLAN_HASH');const p=validatePlan(readJson(raw),Date.now());const ports=await factory(p,digest);return runController(p,ports,digest);}
if(process.argv[1]==='-')main(process.argv.slice(2),process.env).then(result=>{console.log(JSON.stringify(result));if(result.actualExecuted!==false&&result.journey!=='PASSED')process.exitCode=1;}).catch(()=>{console.error(JSON.stringify({status:'REJECTED',code:'IX01_JOURNEY_PREPARATION_REJECTED'}));process.exitCode=1;});
